  var expired=deferredQuote();stays.accept(identity,expired.quote().id(),1,true,key(),correlation());clock.now=expired.quote().effectiveExpiry();assertThatThrownBy(()->stays.amend(identity,b.id(),expired.quote().id(),rejected.version(),true,false,key(),correlation())).isInstanceOf(DomainFailure.class);assertThat(stays.get(identity,b.id()).currentQuote()).isEqualTo(b.quote());
