  var voucher=stays.voucher(identity,b.id(),key(),correlation());assertThat(voucher.id()).isNotEqualTo(original.id());assertThat(voucher.content()).contains("Changed Alex","Room 2");var cancel=stays.cancellationQuote(identity,b.id(),key(),correlation());assertThat(cancel.refundAmount()).isEqualTo(q.newCharge());stays.cancel(identity,b.id(),cancel.id(),true,false,true,key(),correlation());var cancelled=finish(b.id());assertThat(cancelled.refund()).isEqualTo(Refund.SUCCEEDED);assertThat(count("payment_refund","payment_id",done.currentPaymentId())).isEqualTo(1);assertThat(count("payment_refund","payment_id",b.id())).isEqualTo(1);assertThat(supplier.current(b.id()).orElseThrow().activeUnits()).isZero();
