 @Test void prepaidChangeFailureCompensatesReplacementAndPreservesOriginalTerms(){for(var scenario:List.of(Scenario.AUTH_DECLINED,Scenario.CAPTURE_DECLINED,Scenario.RESERVATION_REJECTED)){var b=finish(book(quote("FLEX"),Scenario.SUCCESS).id());var q=changeQuote(b,1,1);assertThat(q.newCharge().amount()).isLessThan(q.expectedRefund().amount());requestChange(b,q,scenario,false,true);var done=finish(b.id());assertThat(done.status()).isEqualTo(Status.CONFIRMED);assertThat(done.currentQuote()).isEqualTo(b.quote());assertThat(done.currentPaymentId()).isEqualTo(b.id());assertThat(done.currentGuests()).isEqualTo(b.guests());assertThat(count("payment_refund","payment_id",b.id())).isZero();assertThat(supplier.current(b.id()).orElseThrow().activeUnits()).isEqualTo(2);if(scenario==Scenario.RESERVATION_REJECTED){assertThat(done.change().state()).isEqualTo(com.travbook.stays.domain.model.StayChange.State.COMPENSATED);assertThat(count("payment_refund","payment_id",done.change().id())).isEqualTo(1);}else assertThat(count("payment_journal","payment_id",done.change().id())).isZero();}}
