 @Test void replacementRefundPendingBlocksCancellationAndDocumentsUntilSettled(){var b=finish(book(quote("FLEX"),Scenario.SUCCESS).id());var q=changeQuote(b,1,1);requestChange(b,q,Scenario.SUCCESS,true,true);for(int i=0;i<15&&stays.get(identity,b.id()).step()!=Step.CHANGE_REFUND_STATUS;i++){due(b.id());worker.tick();}var pending=stays.get(identity,b.id());assertThat(pending.step()).isEqualTo(Step.CHANGE_REFUND_STATUS);assertThat(pending.status()).isEqualTo(Status.PROCESSING);assertThat(pending.change().refund()).isEqualTo(Refund.PENDING);assertThat(pending.currentQuote().id()).isEqualTo(q.details().quote().id());assertThatThrownBy(()->stays.voucher(identity,b.id(),key(),correlation())).isInstanceOf(DomainFailure.class);assertThatThrownBy(()->stays.cancellationQuote(identity,b.id(),key(),correlation())).isInstanceOf(DomainFailure.class);clock.now=clock.now.plusSeconds(6);refunds.settleNext();assertThat(finish(b.id()).change().refund()).isEqualTo(Refund.SUCCEEDED);}
 @Test void concurrentReplacementCommandsAndLostInventoryCompensateOneCapture()throws Exception{var b=finish(book(quote("FLEX"),Scenario.SUCCESS).id());var q=changeQuote(b,2,2);stays.accept(identity,q.details().quote().id(),1,true,key(),correlation());String command=key();try(var pool=Executors.newFixedThreadPool(2)){var results=pool.invokeAll(List.<Callable<Booking>>of(()->stays.change(identity,b.id(),q.details().quote().id(),b.version(),guests(q.details().quote()),Scenario.SUCCESS,true,false,false,command,correlation()),()->stays.change(identity,b.id(),q.details().quote().id(),b.version(),guests(q.details().quote()),Scenario.SUCCESS,true,false,false,command,correlation())));assertThat(results.get(0).get().change().id()).isEqualTo(results.get(1).get().change().id());}for(int i=0;i<10&&stays.get(identity,b.id()).step()!=Step.CHANGE_RESERVE;i++){due(b.id());worker.tick();}assertThat(stays.get(identity,b.id()).step()).isEqualTo(Step.CHANGE_RESERVE);var selected=q.details().quote().selection();var other=UUID.randomUUID();var single=new HotelCriteria(selected.criteria().destination(),selected.criteria().checkIn(),selected.criteria().checkOut(),List.of(selected.criteria().rooms().getFirst()));assertThat(supplier.reserve(new HotelReservations.Command(UUID.randomUUID(),other,single,List.of(selected.offers().getFirst()),q.details().quote().effectiveExpiry(),false)).accepted()).isTrue();var done=finish(b.id());assertThat(done.changes()).hasSize(1);assertThat(done.change().state()).isEqualTo(com.travbook.stays.domain.model.StayChange.State.COMPENSATED);assertThat(done.currentQuote()).isEqualTo(b.quote());assertThat(count("payment_journal","payment_id",done.change().id())).isEqualTo(2);assertThat(count("payment_refund","payment_id",done.change().id())).isEqualTo(1);assertThat(count("payment_refund","payment_id",b.id())).isZero();supplier.cancel(UUID.randomUUID(),other);}

 @Test void inconsistentOriginalFundingStopsBeforeReplacementAuthorization(){var b=finish(book(quote("FLEX"),Scenario.SUCCESS).id());var q=changeQuote(b,1,1);requestChange(b,q,Scenario.SUCCESS,false,false);worker.tick();var bad=new com.travbook.payments.application.port.in.PaymentOperations(){public Optional<Receipt> lookup(UUID op){return Optional.empty();}public Optional<Current> current(UUID id){var actual=paymentOperations.current(id).orElseThrow();return Optional.of(new Current(actual.paymentId(),UUID.randomUUID(),actual.state(),actual.amount(),actual.currency(),actual.mode(),actual.reference(),actual.committedRefunds(),actual.settledRefunds()));}public Receipt execute(Command c){throw new AssertionError("Do not charge against unverified original funding");}};var guarded=new StayWorker(store,selections,new com.travbook.stays.adapter.out.commerce.StayEffectAdapter(bad,refunds,supplier),clock);for(int i=0;i<6;i++){due(b.id());guarded.tick();}var review=stays.get(identity,b.id());assertThat(review.status()).isEqualTo(Status.REVIEW);assertThat(count("payment_operation","payment_id",review.change().id())).isZero();assertThat(supplier.current(b.id()).orElseThrow().activeUnits()).isEqualTo(2);}
 int child(String phase)throws Exception{Path log=temp.resolve(phase+".log");String cp=System.getProperty("surefire.test.class.path",System.getProperty("java.class.path"));var builder=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin","java").toString(),"-cp",cp,"com.travbook.support.StayProcess",phase).redirectErrorStream(true).redirectOutput(log.toFile());builder.environment().put("DATABASE_URL",postgres.getJdbcUrl());builder.environment().put("DATABASE_USERNAME",postgres.getUsername());builder.environment().put("DATABASE_PASSWORD",postgres.getPassword());var process=builder.start();boolean done=process.waitFor(30,TimeUnit.SECONDS);if(!done)process.destroyForcibly();assertThat(done).isTrue();int code=process.exitValue();if(code!=0&&code!=29)throw new AssertionError(Files.readString(log));return code;}
